// ADR-051: Safe division helper functions

static inline bool cnx_safe_mod_u32(uint32_t* output, uint32_t numerator, uint64_t divisor, uint32_t defaultValue) {
    if (divisor == 0) {
        *output = defaultValue;
        return true;  // Error occurred
    }
    /* ADR-044 / Issue #2415: the divisor is the WIDER type (Issue #94), so a value past
       the type reaches here whole. It exceeds every numerator: the quotient is 0 and the
       remainder the numerator. Below it the divisor fits, so the cast after this is exact
       and the division stays in the type's own width. */
    if (divisor > UINT32_MAX) {
        *output = numerator;
        return false;  // Success
    }
    *output = numerator % (uint32_t)divisor;
    return false;  // Success
}

// ADR-051: Basic safe modulo tests
// Tests the safe_mod() built-in function with valid and zero divisors
void testSafeModBasic(void) {
    uint32_t result = 0U;
    bool err = false;
    err = cnx_safe_mod_u32(&result, 10, 3, 0);
    result = 100U;
    err = cnx_safe_mod_u32(&result, 10, 0, 99);
    result = 42U;
    err = cnx_safe_mod_u32(&result, 10, 0, result);
}

void testSafeModEdgeCases(void) {
    uint32_t result = 0U;
    bool err = false;
    err = cnx_safe_mod_u32(&result, 0, 5, 999);
    err = cnx_safe_mod_u32(&result, 10, 10, 0);
    err = cnx_safe_mod_u32(&result, 5, 10, 0);
}

